style.css:
/* EGO — FACEIT Edition */

/* colors — swap these values if you want */
:root {
    --my-black: #080808;
    --my-dark: #111111;
    --my-panel: #181818;
    --my-white: #f5f5f5;
    --my-grey: #929292;
    --my-border: #292929;
}

/* main background and typography */
body {
    background: var(--my-black) !important;
    color: var(--my-white) !important;
    font-family: Arial, Helvetica, sans-serif !important;
}

/* headings and text */
h1, h2, h3, h4, h5 {
    color: var(--my-white) !important;
    font-weight: 800 !important;
    letter-spacing: -0.5px !important;
}

/* links */
a {
    color: var(--my-white) !important;
}

/* buttons */
button {
    border-radius: 5px !important;
    font-weight: 800 !important;
    transition: all 0.2s ease !important;
}

button:hover {
    filter: brightness(0.8) !important;
}

/* inputs */
input, textarea {
    background: var(--my-dark) !important;
    color: var(--my-white) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 5px !important;
}

/* images */
img {
    border-radius: 4px;
}
